fony','2026-10-11 16:18:55','2026-10-11 16:18:55'),(214,16,'settings.updated',NULL,NULL,NULL,'{\"keys\": [\"analytics.ga_enabled\", \"analytics.ga_measurement_id\", \"analytics.pixel_enabled\"], \"group\": \"analytics\"}','127.0.0.1','Symfony','2026-10-11 16:18:55','2026-10-11 16:18:55'),(215,16,'role.permissions_synced','App\\Models\\Role',5,NULL,'{\"count\": 6}','127.0.0.1','Symfony','2026-10-11 16:18:55','2026-10-11 16:18:55'),(216,15,'property.approved','App\\Models\\Property',60,'{\"status\": \"published\"}','{\"status\": \"published\"}','172.21.0.1','Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/132.0.0.0 Safari/537.36','2026-10-12 16:44:16','2026-10-12 16:44:16'),(217,16,'property.created','App\\Models\\Property',78,NULL,'{\"reference_code\": \"DAR-2026-XRVEOQ\"}','172.21.0.1','Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/132.0.0.0 Safari/537.36','2026-10-12 17:52:15','2026-10-12 17:52:15'),(218,16,'property.approved','App\\Models\\Property',78,'{\"status\": \"draft\"}','{\"status\": \"published\"}','172.21.0.1','Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/132.0.0.0 Safari/537.36','2026-10-12 17:52:17','2026-10-12 17:52:17'),(219,16,'property.created','App\\Models\\Property',79,NULL,'{\"reference_code\": \"DAR-2026-89BRXE\"}','172.21.0.1','Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/132.0.0.0 Safari/537.36','2026-10-12 17:53:55','2026-10-12 17:53:55'),(220,16,'property.approved','App\\Models\\Property',79,'{\"status\": \"draft\"}','{\"status\": \"published\"}','172.21.0.1','Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) HeadlessChrome/132.0.0.0 Safari/537.36','2026-10-12 17:53:57','2026-10-12 17:53:57');
