LOCK TABLES `career_translations` WRITE;
/*!40000 ALTER TABLE `career_translations` DISABLE KEYS */;
INSERT INTO `career_translations` VALUES (1,1,'en','Real Estate Broker','data-science-specialist-analytics-division','We are looking for a broker with knowledge of the Beni Suef market to close sale and rental deals and manage clients from first enquiry to contract signing.','Responsibilities:\n- Handle enquiries from clients looking to buy or rent residential and commercial units, understand their needs and budget and match them with suitable offers.\n- Accompany clients on viewings, explain specifications, advantages and the surrounding area, and answer questions clearly and honestly.\n- Maintain an up-to-date list of available offers and coordinate between seller and buyer, or landlord and tenant, until the deal is completed.\n- Negotiate price and terms on behalf of the client while respecting the minimum price agreed with the owner.\n- Follow up contract and registration procedures with the relevant departments and keep an accurate record of every deal and client.\n- Meet a monthly target for viewings and closed deals and comply with company policy on client handling.\n\nRequirements:\n- Secondary or university education and one to three years of experience in real estate brokerage or sales.\n- Good knowledge of Beni Suef districts, roads and market prices, and the ability to travel to sites.\n- Strong communication and negotiation skills, the ability to work under pressure, and comfortable use of computers and basic applications.\n- Commitment to professional ethics and confidentiality when handling client data.\n\nPreference will be given to candidates with a syndicate membership or real estate marketing training, and basic English for dealing with foreign clients.\n\nWe offer a basic monthly salary plus commission on every deal, training on our working systems, and a stable working environment in Beni Suef.','Real Estate Broker','We are looking for a broker with knowledge of the Beni Suef market to close sale and rental deals and manage clients from first enquiry to contract signing.'),(2,1,'ar','سمسار عقارات','data-science-specialist-analytics-division-ar','مطلوب سمسار عقارات بخبرة في سوق بني سويف لإتمام صفقات البيع والإيجار ومتابعة العملاء من أول استفسار حتى توقيع العقد.','المسؤوليات:\n- استقبال طلبات العملاء الباحثين عن شراء أو إيجار وحدة سكنية أو تجارية، وفهم احتياجاتهم وميزانيتهم وتحديد العروض المناسبة لهم.\n- معاينة الوحدات مع العملاء وشرح مواصفاتها ومزاياها والمنطقة المحيطة بها والإجابة عن استفساراتهم بوضوح وأمانة.\n- إعداد قوائم بالعروض المتاحة وتحديثها باستمرار، والتنسيق بين البائع والمشتري أو المالك والمستأجر حتى إتمام التعاقد.\n- التفاوض على السعر والشروط بالنيابة عن العميل مع الالتزام بالسعر الأدنى المتفق عليه مع المالك.\n- متابعة إجراءات التعاقد والتوثيق مع الإدارات المختصة، والاحتفاظ بسجل دقيق لكل صفقة وكل عميل.\n- تحقيق هدف شهري للمعاينات والصفقات والالتزام بسياسات الشركة في التعامل مع العملاء.\n\nالمتطلبات:\n- مؤهل متوسط أو جامعي، وخبرة من سنة إلى ثلاث سنوات في الوساطة العقارية أو المبيعات.\n- معرفة جيدة بأحياء بني سويف وطرقها وأسعار السوق فيها، والقدرة على التنقل ميدانيًا.\n- مهارات تواصل وتفاوض والقدرة على العمل تحت ضغط، وإجادة استخدام الحاسب والتطبيقات الأساسية.\n- الالتزام بأخلاقيات المهنة والسرية في التعامل مع بيانات العملاء.\n\nيفضل من لديه عضوية نقابة أو دورات في التسويق العقاري، ومن يجيد لغة إنجليزية أساسية للتعامل مع العملاء الأجانب.\n\nنقدم راتبًا شهريًا أساسيًا بالإضافة إلى عمولة على كل صفقة، وتدريبًا على أنظمة العمل، وبيئة عمل مستقرة في مدينة بني سويف.','سمسار عقارات','مطلوب سمسار عقارات بخبرة في سوق بني سويف لإتمام صفقات البيع والإيجار ومتابعة العملاء من أول استفسار حتى توقيع العقد.'),(6,2,'en','Accountant','financial-analyst-investment-group','We are hiring an accountant to handle daily financial transactions, prepare monthly reports and follow up installments, rents and tax obligations.','Responsibilities:\n- Record daily financial transactions, prepare journal entries and reconcile bank and cash accounts.\n- Prepare monthly and quarterly reports on revenue, expenses and the return on each project or unit.\n- Follow up client installments and rent collection, update account balances and produce statements of overdue amounts.\n- Prepare tax and social insurance documentation and meet all statutory payment deadlines.\n- Take part in periodic inventory of assets and stock and review maintenance and purchase documents.\n- Support management in preparing budgets, monitoring variances and making recommendations.\n\nRequirements:\n- Bachelor\'s degree in commerce, accounting major, with two to four years of relevant experience.\n- Strong command of accounting software and Excel, and the ability to handle high volumes of transactions accurately.\n- Knowledge of Egyptian tax and social insurance law and the required documentation.\n- High integrity and accuracy with numbers, and the ability to organise files and work within a team.\n\nExperience in real estate development or property management companies, or a professional financial accounting certificate, is an advantage.','Accountant','We are hiring an accountant to handle daily financial transactions, prepare monthly reports and follow up installments, rents and tax obligations.'),(7,2,'ar','محاسب','financial-analyst-investment-group-ar','مطلوب محاسب لمتابعة العمليات المالية اليومية وإعداد التقارير الشهرية ومتابعة الأقساط والإيجارات والالتزامات الضريبية.','المسؤوليات:\n- تسجيل العمليات المالية اليومية وإعداد القيود المحاسبية ومطابقة الحسابات البنكية والصناديق.\n- إعداد التقارير الشهرية والربع سنوية عن الإيرادات والمصروفات وعائد كل مشروع أو وحدة.\n- متابعة أقساط العملاء وتحصيل الإيجارات وتحديث أرصدة الحسابات وإعداد كشوف المتأخرات.\n- إعداد مستندات الضرائب والتأمينات الاجتماعية والالتزام بمواعيد السداد النظامية.\n- المشاركة في الجرد الدوري للأصول والمخزون ومراجعة مستندات الصيانة والمشتريات.\n- مساعدة الإدارة في إعداد الموازنات التقديرية ومتابعة الانحرافات وتقديم المقترحات.\n\nالمتطلبات:\n- بكالوريوس تجارة قسم محاسبة، وخبرة من سنتين إلى أربع سنوات في مجال مشابه.\n- إجادة برامج المحاسبة وإكسل، والقدرة على التعامل مع أعداد كبيرة من العمليات بدقة.\n- معرفة بقوانين الضرائب المصرية والتأمينات الاجتماعية والمستندات المطلوبة.\n- أمانة ودقة عالية في الأرقام، والقدرة على تنظيم الملفات والعمل ضمن فريق.\n\nيفضل من لديه خبرة في شركات التطوير العقاري أو إدارة الأملاك، أو شهادة مهنية في المحاسبة المالية.','محاسب','مطلوب محاسب لمتابعة العمليات المالية اليومية وإعداد التقارير الشهرية ومتابعة الأقساط والإيجارات والالتزامات الضريبية.'),(11,3,'en','Civil Engineer (Property Inspector)','operations-manager-supply-chain-division','We are hiring a civil engineer to inspect properties, assess their structural condition, prepare technical reports and estimate repair and finishing costs.','Responsibilities:\n- Inspect properties offered for sale or rent, assess their structural and finishing condition and produce written technical reports.\n- Measure actual areas, compare them with documents and drawings, identify discrepancies and document them with photographs.\n- Examine plumbing, electrics and finishes, record defects, estimate repair costs and make recommendations to the owner or buyer.\n- Supervise maintenance and finishing work and confirm it matches the specification and schedule.\n- Prepare quantity surveys and preliminary cost estimates for restoration and finishing in coordination with the finance department.\n- Review building permits and technical documents and confirm the unit complies with requirements before it is listed.\n\nRequirements:\n- Bachelor\'s degree in civil engineering and three to five years of experience, preferably in contracting or real estate development.\n- Proficiency in AutoCAD and Excel and the ability to write clear, well-organised technical reports.\n- A driving licence to travel between sites in Beni Suef and the surrounding area.\n- Commitment to safety standards and honesty in assessment, and the ability to work in the field under deadline pressure.','Civil Engineer (Property Inspector)','We are hiring a civil engineer to inspect properties, assess their structural condition, prepare technical reports and estimate repair and finishing costs.'),(12,3,'ar','مهندس مدني للمعاينة','operations-manager-supply-chain-division-ar','مطلوب مهندس مدني لمعاينة الوحدات العقارية وتقييم حالتها الإنشائية وإعداد تقارير فنية وتقدير تكاليف الإصلاح والتشطيب.','المسؤوليات:\n- معاينة الوحدات العقارية المطروحة للبيع أو الإيجار وتقييم حالتها الإنشائية والتشطيبية وإعداد تقارير فنية مكتوبة.\n- قياس المساحات الفعلية ومطابقتها بالمستندات والرسومات، وتحديد الفروق وتوثيقها بالصور.\n- فحص السباكة والكهرباء والتشطيبات ورصد العيوب وتقدير تكلفة الإصلاح وتقديم توصيات للمالك أو المشتري.\n- متابعة أعمال الصيانة والتشطيب المنفذة والتأكد من مطابقتها للمواصفات والجداول الزمنية.\n- إعداد حصر كميات وتقديرات تكلفة مبدئية لأعمال الترميم والتشطيب بالتنسيق مع الإدارة المالية.\n- مراجعة رخص البناء والمستندات الفنية والتأكد من مطابقة الوحدة للاشتراطات قبل العرض.\n\nالمتطلبات:\n- بكالوريوس هندسة مدنية، وخبرة من ثلاث إلى خمس سنوات، ويفضل من لديه خبرة في المقاولات أو التطوير العقاري.\n- إجادة أوتوكاد وإكسل، والقدرة على كتابة تقارير فنية واضحة ومنظمة.\n- رخصة قيادة للتنقل بين المواقع في بني سويف وضواحيها.\n- الالتزام بمعايير السلامة والأمانة في التقييم والقدرة على العمل الميداني تحت ضغط المواعيد.','مهندس مدني للمعاينة','مطلوب مهندس مدني لمعاينة الوحدات العقارية وتقييم حالتها الإنشائية وإعداد تقارير فنية وتقدير تكاليف الإصلاح والتشطيب.'),(16,4,'en','Real Estate Marketing Manager','product-marketing-manager-growth-team','We are looking for a real estate marketing manager to build marketing plans, run digital campaigns and lead the marketing team towards sales targets.','Responsibilities:\n- Build an annual marketing plan for projects and listed units, identify the target audience and select the channels to reach it.\n- Manage digital campaigns on social media and property platforms, measure performance and optimise budget allocation.\n- Oversee production of marketing content, including photos, videos and unit descriptions, working with the photography and design team.\n- Analyse competitors and market prices and submit regular reports to management on campaign results and leads.\n- Lead, train and organise the marketing team, monitor performance and contribute to shared sales targets.\n- Build relationships with developers, brokers and property platforms to increase the reach of listed projects.\n\nRequirements:\n- Bachelor\'s degree in marketing, business administration or equivalent, with four to six years of experience, at least two of them in real estate marketing.\n- Strong command of paid advertising, web analytics and CRM tools, and the ability to read numbers and make decisions.\n- Strong leadership and communication skills and the ability to run several campaigns at once.\n- Knowledge of the property market in Beni Suef and Greater Cairo, and an understanding of the Egyptian buyer\'s needs.','Real Estate Marketing Manager','We are looking for a real estate marketing manager to build marketing plans, run digital campaigns and lead the marketing team towards sales targets.'),(17,4,'ar','مدير تسويق عقاري','product-marketing-manager-growth-team-ar','مطلوب مدير تسويق عقاري لإعداد الخطط التسويقية وإدارة الحملات الرقمية وقيادة فريق التسويق لتحقيق أهداف المبيعات.','المسؤوليات:\n- إعداد خطة تسويقية سنوية للمشروعات والوحدات المعروضة وتحديد الجمهور المستهدف وقنوات الوصول إليه.\n- إدارة الحملات الرقمية على وسائل التواصل والمنصات العقارية وقياس أدائها وتحسين توزيع الميزانية.\n- الإشراف على إنتاج المحتوى التسويقي من صور وفيديوهات ووصف للوحدات بالتنسيق مع فريق التصوير والتصميم.\n- تحليل المنافسين وأسعار السوق ورفع تقارير دورية للإدارة عن نتائج الحملات والعملاء المحتملين.\n- قيادة فريق التسويق وتدريبه وتوزيع المهام ومتابعة الأداء وتحقيق أهداف المبيعات المشتركة.\n- بناء علاقات مع المطورين والوسطاء والمنصات العقارية لزيادة انتشار المشروعات المعروضة.\n\nالمتطلبات:\n- بكالوريوس تسويق أو إدارة أعمال أو ما يعادلها، وخبرة من أربع إلى ست سنوات منها سنتان على الأقل في التسويق العقاري.\n- إجادة الإعلانات المدفوعة وتحليلات المواقع وأدوات إدارة العملاء، والقدرة على قراءة الأرقام واتخاذ القرار.\n- مهارات قيادة وتواصل قوية، والقدرة على إدارة أكثر من حملة في وقت واحد.\n- معرفة بسوق العقارات في بني سويف والقاهرة الكبرى، وفهم احتياجات المشتري المصري.','مدير تسويق عقاري','مطلوب مدير تسويق عقاري لإعداد الخطط التسويقية وإدارة الحملات الرقمية وقيادة فريق التسويق لتحقيق أهداف المبيعات.'),(21,5,'en','Property Sales Representative','senior-full-stack-engineer-creator-success-full-time','We are hiring a property sales representative to present units, explain installment plans and follow clients through to contract and monthly targets.','Responsibilities:\n- Contact leads generated by marketing campaigns and exhibitions and schedule viewing appointments.\n- Present units, explain their advantages and available installment plans, and match them to the client\'s needs and budget.\n- Follow up with clients after viewings, answer questions and complete reservation and contracting procedures.\n- Prepare weekly reports on sales, follow-ups and leads and submit them to the sales manager.\n- Meet a monthly sales target and coordinate with marketing and customer service to ensure client satisfaction.\n- Represent the company at local property exhibitions and events in Beni Suef.\n\nRequirements:\n- University or secondary education and at least one year of sales experience, preferably in property or cars.\n- Strong presentation and persuasion skills, diplomacy and the ability to build trusting relationships with clients.\n- Punctuality and the ability to work in the field and visit different sites.\n- Comfortable use of computers and customer management software.\n\nWe offer a basic salary, generous commission and bonuses for achieving monthly targets, plus training on our property products.','Property Sales Representative','We are hiring a property sales representative to present units, explain installment plans and follow clients through to contract and monthly targets.'),(22,5,'ar','مندوب مبيعات عقارية','senior-full-stack-engineer-creator-success-full-time-ar','مطلوب مندوب مبيعات عقارية لعرض الوحدات على العملاء وشرح خطط التقسيط ومتابعتهم حتى إتمام التعاقد وتحقيق هدف البيع الشهري.','المسؤوليات:\n- التواصل مع العملاء المحتملين الواردين من الحملات التسويقية والمعارض وترتيب مواعيد المعاينة.\n- عرض الوحدات وشرح مزاياها وخطط التقسيط المتاحة ومقارنتها باحتياج العميل وميزانيته.\n- متابعة العملاء بعد المعاينة والإجابة عن استفساراتهم وإتمام إجراءات الحجز والتعاقد.\n- إعداد تقارير أسبوعية بالمبيعات والمتابعات والعملاء المحتملين ورفعها لمدير المبيعات.\n- تحقيق هدف بيع شهري والتنسيق مع فريق التسويق وخدمة العملاء لضمان رضا العميل.\n- تمثيل الشركة في المعارض والمناسبات العقارية المحلية داخل بني سويف.\n\nالمتطلبات:\n- مؤهل جامعي أو متوسط، وخبرة سنة على الأقل في المبيعات ويفضل في العقارات أو السيارات.\n- مهارات عرض وإقناع ولباقة والقدرة على بناء علاقات ثقة مع العملاء.\n- الالتزام بالمواعيد والقدرة على العمل الميداني وزيارة المواقع المختلفة.\n- إجادة استخدام الحاسب وبرامج إدارة العملاء.\n\nنقدم راتبًا أساسيًا وعمولة مجزية وحوافز على تحقيق الأهداف الشهرية، وتدريبًا على المنتجات العقارية.','مندوب مبيعات عقارية','مطلوب مندوب مبيعات عقارية لعرض الوحدات على العملاء وشرح خطط التقسيط ومتابعتهم حتى إتمام التعاقد وتحقيق هدف البيع الشهري.'),(26,6,'en','Customer Service Officer','uxui-designer-user-experience-team','We are hiring a customer service officer to answer client enquiries, track complaints, coordinate appointments and ensure a good experience before and after signing.','Responsibilities:\n- Answer client enquiries by phone, WhatsApp and email and provide accurate information about units and services.\n- Log complaints and follow-ups in the CRM, pursue them with the relevant departments until closure and inform the client of the outcome.\n- Coordinate appointments between clients, the sales team and engineers and arrange viewing visits.\n- Follow up with clients after a sale or contract, confirm satisfaction, collect feedback and pass new opportunities to the sales team.\n- Prepare regular reports on enquiry and complaint volumes and recurring issues, and suggest service improvements.\n- Keep the client database accurate and up to date and comply with privacy policies.\n\nRequirements:\n- University degree and one to three years of customer service experience, preferably in real estate or financial services.\n- Excellent communication skills in Arabic with basic English, and diplomacy in handling complaints.\n- Confident use of computers and CRM systems, with good organisation and teamwork.\n- The ability to work to tight schedules while keeping the client calm and finding practical solutions.','Customer Service Officer','We are hiring a customer service officer to answer client enquiries, track complaints, coordinate appointments and ensure a good experience before and after sig'),(27,6,'ar','مسؤول خدمة عملاء','uxui-designer-user-experience-team-ar','مطلوب مسؤول خدمة عملاء للرد على استفسارات العملاء ومتابعة الشكاوى وتنسيق المواعيد وضمان تجربة جيدة قبل التعاقد وبعده.','المسؤوليات:\n- الرد على استفسارات العملاء عبر الهاتف والواتساب والبريد الإلكتروني وتقديم معلومات دقيقة عن الوحدات والخدمات.\n- تسجيل الشكاوى والمتابعات في نظام إدارة العملاء ومتابعتها مع الإدارات المعنية حتى الإغلاق وإبلاغ العميل بالنتيجة.\n- تنسيق المواعيد بين العملاء وفريق المبيعات والمهندسين وترتيب زيارات المعاينة.\n- متابعة العملاء بعد البيع أو التعاقد والتأكد من رضاهم وجمع ملاحظاتهم وتحويل الفرص الجديدة إلى فريق المبيعات.\n- إعداد تقارير دورية عن حجم الاستفسارات والشكاوى وأكثر الموضوعات تكرارًا واقتراح تحسينات للخدمة.\n- الحفاظ على قاعدة بيانات العملاء محدثة ودقيقة والالتزام بسياسات الخصوصية.\n\nالمتطلبات:\n- مؤهل جامعي، وخبرة من سنة إلى ثلاث سنوات في خدمة العملاء، ويفضل في العقارات أو الخدمات المالية.\n- مهارات تواصل ممتازة بالعربية مع إجادة أساسية للإنجليزية، ولباقة في التعامل مع الشكاوى.\n- إجادة استخدام الحاسب وأنظمة إدارة العملاء، والقدرة على التنظيم والعمل ضمن فريق.\n- القدرة على العمل بمواعيد ضاغطة والحفاظ على هدوء العميل وإيجاد حلول عملية.','مسؤول خدمة عملاء','مطلوب مسؤول خدمة عملاء للرد على استفسارات العملاء ومتابعة الشكاوى وتنسيق المواعيد وضمان تجربة جيدة قبل التعاقد وبعده.'),(31,7,'ar','مستشار مبيعات واستثمار عقاري أول','senior-real-estate-sales-advisor-ar','مطلوب مستشار مبيعات عقارية متميز للتواصل مع كبار العملاء والمستثمرين وتقديم استشارات شراء للمشروعات السكنية والتجارية في بني سويف.','المسؤوليات:\n- استقبال العملاء والرد على استفساراتهم وتقديم العروض الاستثمارية المناسبة لاحتياجاتهم وميزانياتهم.\n- تنظيم وإجراء جولات المعاينة الميدانية للوحدات السكنية والتجارية والأراضي.\n- متابعة مراحل التفاوض وإتمام التعاقدات وفق النماذج القانونية المعتمدة.\n- بناء شبكة علاقات قوية مع كبار المستثمرين والمطورين العقاريين.\n\nالمتطلبات:\n- خبرة لا تقل عن 3 سنوات في مجال المبيعات والوساطة العقارية.\n- إجادة تامة لمهارات الإقناع والتفاوض وخدمة العملاء.\n- معرفة شاملة بالمناطق السكنية والاستثمارية بمحافظة بني سويف.\n- مهارات اتصال ممتازة وحضور مهني راقٍ.','مستشار مبيعات واستثمار عقاري أول | وظائف دارلي','مطلوب مستشار مبيعات عقارية متميز للتواصل مع كبار العملاء والمستثمرين وتقديم استشارات شراء للمشروعات السكنية والتجارية في بني سويف.'),(32,7,'en','Senior Real Estate Investment Advisor','senior-real-estate-sales-advisor','Seeking an accomplished real estate sales consultant to guide buyers and investors towards premium residential and commercial assets in Beni Suef.','Responsibilities:\n- Meet prospective buyers and evaluate their investment requirements.\n- Arrange and host physical viewings across prime developments.\n- Negotiate deals and support contract signing.\n\nRequirements:\n- 3+ years experience in property brokerage.\n- Strong negotiation and communication skills.\n- Deep knowledge of Beni Suef property market.','Senior Real Estate Investment Advisor | وظائف دارلي','Seeking an accomplished real estate sales consultant to guide buyers and investors towards premium residential and commercial assets in Beni Suef.'),(33,8,'ar','مهندس تقييم عقاري وتسعير معتمد','property-valuation-engineer-ar','مهندس مدني / معماري متخصص في التقييم الهندسي والفحص الإنشائي للوحدات العقارية وإعداد تقارير القيمة العادلة المعتمدة.','المسؤوليات:\n- إجراء المعاينات الهندسية والفحص الإنشائي للوحدات والمباني السكنية والتجارية.\n- دراسة الموقع وسعر المتر ومؤشرات السوق لتحديد القيمة السوقية العادلة بدقة.\n- إعداد تقارير التقييم العقاري المعتمدة لعملاء المنصة والبنوك الشريكة.\n- التأكد من مطابقة المباني للتراخيص الهندسية الصادرة.\n\nالمتطلبات:\n- بكالوريوس هندسة مدنية أو عمارة.\n- خبرة 3-5 سنوات في التقييم العقاري والفحص الفني.\n- عضوية نقابة المهندسين المصرية وشهادة مقيم عقاري معتمد ميزة إضافية.','مهندس تقييم عقاري وتسعير معتمد | وظائف دارلي','مهندس مدني / معماري متخصص في التقييم الهندسي والفحص الإنشائي للوحدات العقارية وإعداد تقارير القيمة العادلة المعتمدة.'),(34,8,'en','Certified Property Valuation Engineer','property-valuation-engineer','Civil/Architectural engineer specialised in structural inspection and market valuation for residential and commercial assets.','Responsibilities:\n- Conduct site technical inspections of properties.\n- Analyze market benchmarks to determine fair market value.\n- Issue certified valuation reports.','Certified Property Valuation Engineer | وظائف دارلي','Civil/Architectural engineer specialised in structural inspection and market valuation for residential and commercial assets.'),(35,9,'ar','أخصائي تسويق رقمي وحملات عقارية','digital-real-estate-marketer-ar','مطلوب متخصص في إدارة الحملات الإعلانية الممولة (Facebook, Google, TikTok) وصناعة المحتوى العقاري الجذاب.','المسؤوليات:\n- تخطيط وإدارة الحملات الإعلانية الممولة للمشروعات العقارية وجلب العملاء المحتملين (Lead Generation).\n- إنتاج محتوى مرئي وجذاب للمشروعات العقارية عبر منصات التواصل الاجتماعي.\n- تحليل أداء الحملات وتحسين معدلات التحويل وخفض تكلفة العميل.\n\nالمتطلبات:\n- خبرة موثقة في الحملات الرقمية للقطاع العقاري.\n- إجادة التعامل مع Meta Ads Manager و Google Ads وأدوات التحليل.\n- مهارات كتابة إعلانية (Copywriting) مؤثرة.','أخصائي تسويق رقمي وحملات عقارية | وظائف دارلي','مطلوب متخصص في إدارة الحملات الإعلانية الممولة (Facebook, Google, TikTok) وصناعة المحتوى العقاري الجذاب.'),(36,9,'en','Digital Real Estate Marketing Specialist','digital-real-estate-marketer','Paid media specialist to execute lead generation campaigns across Meta, Google, and video channels.','Responsibilities:\n- Plan and optimize real estate lead generation campaigns.\n- Craft engaging property content.\n- Maximize ROI and conversion rates.','Digital Real Estate Marketing Specialist | وظائف دارلي','Paid media specialist to execute lead generation campaigns across Meta, Google, and video channels.'),(37,10,'ar','مستشار قانوني وتوثيق عقود عقارية','real-estate-legal-counsel-ar','محامٍ مقيد بالاستئناف متخصص في فحص الملكيات العقارية وتوثيق عقود البيع والشراء وإجراءات الشهر العقاري.','المسؤوليات:\n- مراجعة تسلسل ملكية العقارات والأراضي والتأكد من خلوها من أي موانع قانونية أو نزاعات.\n- صياغة وتدقيق عقود البيع والشراء والإيجار والاتفاقيات بين الأطراف.\n- توجيه العملاء في إجراءات التسجيل بالشهر العقاري ودعاوى صحة ونفاذ العقد.\n\nالمتطلبات:\n- ليسانس حقوق مع قيد نقابي سارٍ (استئناف على الأقل).\n- خبرة عملية واسعة في قضايا العقارات والشهر العقاري بمحافظة بني سويف.\n- دقة عالية وأمانة مهنية.','مستشار قانوني وتوثيق عقود عقارية | وظائف دارلي','محامٍ مقيد بالاستئناف متخصص في فحص الملكيات العقارية وتوثيق عقود البيع والشراء وإجراءات الشهر العقاري.'),(38,10,'en','Real Estate Legal Counsel','real-estate-legal-counsel','Corporate property attorney experienced in title deeds verification and real estate contract conveyance.','Responsibilities:\n- Verify title deeds chain and clearance.\n- Draft and audit purchase and lease agreements.\n- Guide clients through land registry protocols.','Real Estate Legal Counsel | وظائف دارلي','Corporate property attorney experienced in title deeds verification and real estate contract conveyance.');
