INSERT INTO `project_translations` VALUES (1,1,'en','Nile Gardens Compound','adarsh-greens','An integrated residential development in Beni Suef City with varied unit sizes and flexible payment plans.','Nile Gardens Compound is an integrated residential development in Beni Suef City, Beni Suef Governorate, comprising 4 buildings of roughly 4 floors and 64 residential units in a range of sizes suited to both small and large families.\n\nThe master plan includes landscaped green areas, children playgrounds, internal roads and ample parking for every building.\n\nUnits are handed over with good finishes, and buyers can choose the finishing level that suits them; some layouts can be modified to their preference.\n\nThe site is minutes from essential services, schools and the university, and sits close to a main transport axis linking the city with its neighbours.\n\nFlexible payment: a down payment starting from 15% with installments up to six years interest-free, plus an extra discount for cash buyers.\n\nThe project is officially registered and contracts are documented. A site visit can be arranged at any time through the Darlii team.','Nile Gardens Compound — Beni Suef City','Nile Gardens Compound is an integrated residential development in Beni Suef City, Beni Suef Governorate, comprising 4 buildings of roughly 4 floors and 64...'),(2,1,'ar','كمبوند النيل جاردنز','mashrou-1-ar','مشروع سكني متكامل في مدينة بني سويف بمساحات متنوعة وخطط سداد مرنة.','كمبوند النيل جاردنز مشروع سكني متكامل في مدينة بني سويف بمحافظة بني سويف، مكوّن من 4 عمارة بإجمالي 4 دور تقريباً و64 وحدة سكنية بمساحات متنوعة تناسب الأسرة الصغيرة والكبيرة.\n\nيتضمن المشروع تصميم معماري حديث يوفر تهوية وإضاءة طبيعية لكل وحدة، ومساحات خضراء ومناطق لعب للأطفال داخل المشروع، وشبكة طرق داخلية ومواقف سيارات كافية لكل عمارة.\n\nالوحدات تُسلَّم بتشطيبات جيدة ويمكن للعميل اختيار مستوى التشطيب المناسب له، مع إمكانية تعديل التقسيم الداخلي في بعض النماذج.\n\nيقع المشروع على بعد دقائق من الخدمات الأساسية والمدارس والجامعة، وقريب من محور مواصلات رئيسي يربط المدينة بالمدن المجاورة.\n\nنظام السداد مرن: مقدم يبدأ من 15% وتقسيط يصل إلى 6 سنوات بدون فوائد، مع خصم إضافي في حالة السداد النقدي.\n\nالمشروع مسجّل ويتم التعاقد بعقود موثقة، ويمكن الحصول على معاينة على الطبيعة في أي وقت بالتنسيق مع فريق دارلي.','كمبوند النيل جاردنز — مدينة بني سويف','كمبوند النيل جاردنز مشروع سكني متكامل في مدينة بني سويف بمحافظة بني سويف، مكوّن من 4 عمارة بإجمالي 4 دور تقريباً و64 وحدة سكنية بمساحات متنوعة تناسب الأسرة...'),(6,2,'en','Beni Suef Heights','brigade-oasis','An integrated residential development in New Beni Suef City with varied unit sizes and flexible payment plans.','Beni Suef Heights is an integrated residential development in New Beni Suef City, Beni Suef Governorate, comprising 5 buildings of roughly 5 floors and 125 residential units in a range of sizes suited to both small and large families.\n\nThe master plan includes landscaped green areas, children playgrounds, internal roads and ample parking for every building.\n\nUnits are handed over with good finishes, and buyers can choose the finishing level that suits them; some layouts can be modified to their preference.\n\nThe site is minutes from essential services, schools and the university, and sits close to a main transport axis linking the city with its neighbours.\n\nFlexible payment: a down payment starting from 15% with installments up to six years interest-free, plus an extra discount for cash buyers.\n\nThe project is officially registered and contracts are documented. A site visit can be arranged at any time through the Darlii team.','Beni Suef Heights — New Beni Suef City','Beni Suef Heights is an integrated residential development in New Beni Suef City, Beni Suef Governorate, comprising 5 buildings of roughly 5 floors and 125...'),(7,2,'ar','كمبوند بني سويف هايتس','mashrou-2-ar','مشروع سكني متكامل في مدينة بني سويف الجديدة بمساحات متنوعة وخطط سداد مرنة.','كمبوند بني سويف هايتس مشروع سكني متكامل في مدينة بني سويف الجديدة بمحافظة بني سويف، مكوّن من 5 عمارة بإجمالي 5 دور تقريباً و125 وحدة سكنية بمساحات متنوعة تناسب الأسرة الصغيرة والكبيرة.\n\nيتضمن المشروع تصميم معماري حديث يوفر تهوية وإضاءة طبيعية لكل وحدة، ومساحات خضراء ومناطق لعب للأطفال داخل المشروع، وشبكة طرق داخلية ومواقف سيارات كافية لكل عمارة.\n\nالوحدات تُسلَّم بتشطيبات جيدة ويمكن للعميل اختيار مستوى التشطيب المناسب له، مع إمكانية تعديل التقسيم الداخلي في بعض النماذج.\n\nيقع المشروع على بعد دقائق من الخدمات الأساسية والمدارس والجامعة، وقريب من محور مواصلات رئيسي يربط المدينة بالمدن المجاورة.\n\nنظام السداد مرن: مقدم يبدأ من 15% وتقسيط يصل إلى 6 سنوات بدون فوائد، مع خصم إضافي في حالة السداد النقدي.\n\nالمشروع مسجّل ويتم التعاقد بعقود موثقة، ويمكن الحصول على معاينة على الطبيعة في أي وقت بالتنسيق مع فريق دارلي.','كمبوند بني سويف هايتس — مدينة بني سويف الجديدة','كمبوند بني سويف هايتس مشروع سكني متكامل في مدينة بني سويف الجديدة بمحافظة بني سويف، مكوّن من 5 عمارة بإجمالي 5 دور تقريباً و125 وحدة سكنية بمساحات متنوعة ت...'),(11,3,'en','Wasta Residence','diamond-island','An integrated residential development in West Beni Suef with varied unit sizes and flexible payment plans.','Wasta Residence is an integrated residential development in West Beni Suef, Beni Suef Governorate, comprising 6 buildings of roughly 6 floors and 216 residential units in a range of sizes suited to both small and large families.\n\nThe master plan includes landscaped green areas, children playgrounds, internal roads and ample parking for every building.\n\nUnits are handed over with good finishes, and buyers can choose the finishing level that suits them; some layouts can be modified to their preference.\n\nThe site is minutes from essential services, schools and the university, and sits close to a main transport axis linking the city with its neighbours.\n\nFlexible payment: a down payment starting from 15% with installments up to six years interest-free, plus an extra discount for cash buyers.\n\nThe project is officially registered and contracts are documented. A site visit can be arranged at any time through the Darlii team.','Wasta Residence — West Beni Suef','Wasta Residence is an integrated residential development in West Beni Suef, Beni Suef Governorate, comprising 6 buildings of roughly 6 floors and 216 resid...'),(12,3,'ar','كمبوند الواسطى ريزيدنس','mashrou-3-ar','مشروع سكني متكامل في بني سويف الغربية بمساحات متنوعة وخطط سداد مرنة.','كمبوند الواسطى ريزيدنس مشروع سكني متكامل في بني سويف الغربية بمحافظة بني سويف، مكوّن من 6 عمارة بإجمالي 6 دور تقريباً و216 وحدة سكنية بمساحات متنوعة تناسب الأسرة الصغيرة والكبيرة.\n\nيتضمن المشروع تصميم معماري حديث يوفر تهوية وإضاءة طبيعية لكل وحدة، ومساحات خضراء ومناطق لعب للأطفال داخل المشروع، وشبكة طرق داخلية ومواقف سيارات كافية لكل عمارة.\n\nالوحدات تُسلَّم بتشطيبات جيدة ويمكن للعميل اختيار مستوى التشطيب المناسب له، مع إمكانية تعديل التقسيم الداخلي في بعض النماذج.\n\nيقع المشروع على بعد دقائق من الخدمات الأساسية والمدارس والجامعة، وقريب من محور مواصلات رئيسي يربط المدينة بالمدن المجاورة.\n\nنظام السداد مرن: مقدم يبدأ من 15% وتقسيط يصل إلى 6 سنوات بدون فوائد، مع خصم إضافي في حالة السداد النقدي.\n\nالمشروع مسجّل ويتم التعاقد بعقود موثقة، ويمكن الحصول على معاينة على الطبيعة في أي وقت بالتنسيق مع فريق دارلي.','كمبوند الواسطى ريزيدنس — بني سويف الغربية','كمبوند الواسطى ريزيدنس مشروع سكني متكامل في بني سويف الغربية بمحافظة بني سويف، مكوّن من 6 عمارة بإجمالي 6 دور تقريباً و216 وحدة سكنية بمساحات متنوعة تناسب...'),(16,4,'en','Yasmin Compound','godrej-exquisite','An integrated residential development in El Wasta with varied unit sizes and flexible payment plans.','Yasmin Compound is an integrated residential development in El Wasta, Beni Suef Governorate, comprising 7 buildings of roughly 7 floors and 196 residential units in a range of sizes suited to both small and large families.\n\nThe master plan includes landscaped green areas, children playgrounds, internal roads and ample parking for every building.\n\nUnits are handed over with good finishes, and buyers can choose the finishing level th