  `floor_number` smallint unsigned DEFAULT NULL,
  `bedrooms` smallint unsigned DEFAULT NULL,
  `bathrooms` smallint unsigned DEFAULT NULL,
  `area` decimal(12,2) DEFAULT NULL,
  `price` decimal(18,4) DEFAULT NULL,
  `currency_id` bigint unsigned DEFAULT NULL,
  `availability_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'available',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `project_units_project_id_unit_code_unique` (`project_id`,`unit_code`),
  KEY `project_units_property_type_id_foreign` (`property_type_id`),
  KEY `project_units_currency_id_foreign` (`currency_id`),
  KEY `project_units_availability_status_index` (`availability_status`),
  CONSTRAINT `project_units_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `project_units_project_id_foreign` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `project_units_property_type_id_foreign` FOREIGN KEY (`property_type_id`) REFERENCES `property_types` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
