CREATE TABLE `property_nearby_places` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `property_id` bigint unsigned NOT NULL,
  `type` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `distance` decimal(10,2) DEFAULT NULL,
  `distance_unit` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'km',
  `travel_time_minutes` smallint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `property_nearby_places_property_id_foreign` (`property_id`),
  CONSTRAINT `property_nearby_places_property_id_foreign` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`) ON DELETE CASCADE
