INSERT INTO `property_translations` VALUES (1,1,'en','2-Bedroom Apartment in Beni Suef City — for Sale','2-floor-house-in-compound-pejaten-barat-kemang','Apartment for sale spanning 88 m² in Beni Suef City, close to schools, shops and public transport.','2-Bedroom Apartment in Beni Suef City — for Sale — a property located in Beni Suef City, within Beni Suef Governorate.\n\nUnit details: 2 bedrooms and 1 bathrooms, a total area of 88 m², and Super-lux finishing. The unit has independent electricity and water meters and its own entrance.\n\nThe unit suits a family looking for a quiet street while staying a short drive from Beni Suef University.\n\nServices nearby: Beni Suef University, a mosque, a pharmacy, a bakery, a supermarket and a transport stop — everything needed for comfortable daily living.\n\nOffered for sale at 1,820,000 EGP. The price per square metre reflects the location and the services available nearby.\n\nThe area is growing steadily and demand for housing in Beni Suef keeps rising, which makes this a sound medium-term investment.\n\nInstallment plans are available with a down payment starting from 20%; terms can be discussed during the viewing.\n\nTo arrange a viewing or ask about the required paperwork, contact the Darlii team and we will schedule a visit at your convenience.','Nile Gardens Compound, Salah Salem Street, Beni Suef City, Beni Suef Governorate, Egypt','2-Bedroom Apartment in Beni Suef City — for Sale — Beni Suef','2-Bedroom Apartment in Beni Suef City — for Sale — a property located in Beni Suef City, within Beni Suef Governorate.\n\nUnit details: 2 bedrooms and 1 bath...'),(2,1,'ar','شقة 2 غرف – الحي الأول بفيو مفتوح','aqar-1-ar','شقة للبيع بمساحة 88 م² في الحي الأول، مدينة بني سويف — موقع قريب من الخدمات والمواصلات.','شقة 2 غرف – الحي الأول بفيو مفتوح — وحدة عقارية في الحي الأول بمدينة مدينة بني سويف داخل نطاق محافظة بني سويف.\n\nتفاصيل الوحدة: 2 غرف نوم و1 حمام، بمساحة إجمالية 88 متر مربع، وتشطيب سوبر لوكس. الوحدة بها عدادات كهرباء ومياه مستقلة ومدخل مستقل.\n\nالوحدة مناسبة جداً للأسرة المصرية لأنها تجمع بين الهدوء وقربها من جامعة بني سويف.\n\nالخدمات المحيطة: قريبة من جامعة بني سويف، ومسجد، وصيدلية، ومخبز، وسوبر ماركت، وموقف مواصلات، مما يجعل الحياة اليومية مريحة بدون تنقل طويل.\n\nمعروضة للبيع بسعر 1,820,000 جنيه مصري، وسعر المتر في المنطقة يتناسب مع الموقع والخدمات المتاحة.\n\nالوحدة فرصة استثمارية جيدة لأن أسعار بني سويف في نمو مستمر مع الطلب المتزايد على السكن.\n\nيُقبل التقسيط على دفعات مع مقدم يبدأ من 20%، ويمكن مناقشة التفاصيل خلال المعاينة.\n\nللمعاينة أو الاستفسار عن التفاصيل والأوراق المطلوبة، تواصل مع فريق دارلي ويمكن ترتيب زيارة في الوقت الذي يناسبك.','كمبوند النيل جاردنز، شارع صلاح سالم، الحي الأول، مدينة بني سويف، محافظة بني سويف','شقة 2 غرف – الحي الأول بفيو مفتوح — مدينة بني سويف','شقة 2 غرف – الحي الأول بفيو مفتوح — وحدة عقارية في الحي الأول بمدينة مدينة بني سويف داخل نطاق محافظة بني سويف.\n\nتفاصيل الوحدة: 2 غرف نوم و1 حمام، بمساحة إج...'),(6,2,'en','2-Bedroom Apartment in New Beni Suef City — with Open View','3-beds-villa-calpe-alicante','Apartment for sale spanning 111 m² in New Beni Suef City, close to schools, shops and public transport.','2-Bedroom Apartment in New Beni Suef City — with Open View — a property located in New Beni Suef City, within Beni Suef Governorate.\n\nUnit details: 2 bedrooms and 1 bathrooms, a total area of 111 m², and Lux finishing. The unit has independent electricity and water meters and its own entrance.\n\nIt sits in a well-established part of New Beni Suef City where schools, clinics and public transport are all close by.\n\nServices nearby: Beni Suef University Hospital, a mosque, a pharmacy, a bakery, a supermarket and a transport stop — everything needed for comfortable daily living.\n\nOffered for sale at 2,067,000 EGP. The price per square metre reflects the location and the services available nearby.\n\nThe area is growing steadily and demand for housing in Beni Suef keeps rising, which makes this a sound medium-term investment.\n\nInstallment plans are available with a down payment starting from 20%; terms can be discussed during the viewing.\n\nTo arrange a viewing or ask about the required paperwork, contact the Darlii team and we will schedule a visit at your convenience.','Beni Suef Heights, Ahmed Orabi Street, New Beni Suef City, Beni Suef Governorate, Egypt','2-Bedroom Apartment in New Beni Suef City — with Open View —','2-Bedroom Apartment in New Beni Suef City — with Open View — a property located in New Beni Suef City, within Beni Suef Governorate.\n\nUnit details: 2 bedro...'),(7,2,'ar','شقة 2 غرف – الحي الثاني بالمدينة الجديدة قريبة من الخدمات','aqar-2-ar','شقة للبيع بمساحة 111 م² في الحي الثاني بالمدينة الجديدة، مدينة بني سويف الجديدة — موقع قريب من الخدمات والمواصلات.','شقة 2 غرف – الحي الثاني بالمدينة الجديدة قريبة من الخدمات — وحدة عقارية في الحي الثاني بالمدينة الجديدة بمدينة مدينة بني سويف الجديدة داخل نطاق محافظة بني سويف.\n\nتفاصيل الوحدة: 2 غرف نوم و1 حمام، بمساحة إجمالية 111 متر مربع، وتشطيب لوكس. الوحدة بها عدادات كهرباء ومياه مستقلة ومدخل مستقل.\n\nالمكان مختار بعناية في الحي الثاني بالمدينة الجديدة بحيث تكون المدارس والمواصلات في متناول اليد.\n\nالخدمات المحيطة: قريبة من مستشفى بني سويف الجامعي، ومسجد، وصيدلية، ومخبز، وسوبر ماركت، وموقف مواصلات، مما يجعل الحياة اليومية مريحة بدون تنقل طويل.\n\nمعروضة للبيع بسعر 2,067,000 جنيه مصري، وسعر المتر في المنطقة يتناسب مع الموقع والخدمات المتاحة.\n\nمناسب للسكن أو لإعادة الإيجار، والعائد المتوقع مجزٍ مقارنة بأسعار الشراء الحالية.\n\nيُقبل التقسيط على دفعات مع مقدم يبدأ من 20%، ويمكن مناقشة التفاصيل خلال المعاينة.\n\nللمعاينة أو الاستفسار عن التفاصيل والأوراق المطلوبة، تواصل مع فريق دارلي ويمكن ترتيب زيارة في الوقت الذي يناسبك.','كمبوند بني سويف هايتس، شارع أحمد عرابي، الحي الثاني بالمدينة الجديدة، مدينة بني سويف الجديدة، محافظة بني سويف','شقة 2 غرف – الحي الثاني بالمدينة الجديدة قريبة من الخدمات —','شقة 2 غرف – الحي الثاني بالمدينة الجديدة قريبة من الخدمات — وحدة عقارية في الحي الثاني بالمدينة الجديدة بمدينة مدينة بني سويف الجديد