INSERT INTO `testimonial_translations` VALUES (1,1,'en','Jennifer Lee','Happy Home Seeker','From the initial consultation to closing day, the real estate team went above and beyond to ensure I found the perfect home. Their dedication and professionalism made the entire process seamless. Thank you!'),(2,1,'ar','السيدة جينيفر لي','باحث سعيد عن منزل','من الاستشارة الأولى حتى يوم الإغلاق، بذل فريق العقارات جهداً يفوق التوقعات لضمان أن أجد المنزل المثالي. جعلت تفانيهم واحترافيتهم العملية بأكملها سلسة. شكرًا لكم!'),(3,2,'en','Robert Evans','Property Investor','I am impressed by the level of expertise and commitment demonstrated by this real estate team. Their insights into the market helped me make informed investment decisions, and I couldn\'t be happier with the results.'),(4,2,'ar','السيد روبرت إيفانز','مستثمر عقاري','لقد أعجبت بمستوى الخبرة والالتزام الذي أظهره هذا الفريق العقاري. ساعدتني رؤيتهم الثاقبة للسوق في اتخاذ قرارات استثمارية مدروسة، ولا يمكنني أن أكون أكثر سعادة بالنتائج.'),(5,3,'en','Jessica White','Delighted Home Seller','Selling my home with the help of this real estate team was a breeze. They provided valuable advice, staged my property beautifully, and negotiated a great deal. I highly recommend their services to anyone looking to sell their home!'),(6,3,'ar','السيدة جيسيكا وايت','بائع منزل سعيد','كان بيع منزلي بمساعدة هذا الفريق سهلاً للغاية. قدموا نصائح قيّمة، وجهزوا العقار بشكل رائع، وتفاوضوا على صفقة ممتازة. أوصي بخدماتهم بشدة لكل من يرغب في بيع منزله!'),(7,4,'en','Daniel Miller','Happy New Homeowner','Thanks to the expertise and guidance of this real estate team, I am now the proud owner of my dream home. They listened to my preferences, answered all my questions, and made the entire home buying process a positive experience.'),(8,4,'ar','السيد دانيال ميلر','مالك منزل جديد سعيد','بفضل خبرة وإرشاد هذا الفريق، أصبحت الآن المالك الفخور بمنزل أحلامي. استمعوا إلى تفضيلاتي، وأجابوا عن جميع أسئلتي، وجعلوا عملية شراء المنزل تجربة إيجابية.');
/*!40000 ALTER TABLE `testimonial_translations` ENABLE KEYS */;
UNLOCK TABLES;

